class Solution {
public:
    int divisibleTripletCount(vector<int>& nums, int d) {
        int n = nums.size(), ans = 0;
        for (int j = 1; j < n - 1; ++j) {
            vector<int> count(d);
            for (int i = 0; i < j; ++i) ++count[((nums[i] % d) + d) % d];
            for (int k = j + 1; k < n; ++k) {
                int rem = ((nums[j] + nums[k]) % d + d) % d;
                ans += count[(d - rem) % d];
            }
        }
        return ans;
    }
};
